const init = $input.first().json;
const g = $getWorkflowStaticData('global');
g.loop_state = {
  cumul_tokens:         0,
  cumul_input_tokens:   0,
  prev_answer:          '',
  max_iterations:       3,
  input_text:           init.input_text,
  start_time_ms:        init.start_time_ms,
  input_token_estimate: init.input_token_estimate,
  iterations_trace:     [],
  current_prompt_text:  ''
};
// 3 slots — safety cap is now iteration 3
return [1, 2, 3].map(i => ({ json: {
  iteration:            i,
  input_text:           init.input_text,
  start_time_ms:        init.start_time_ms,
  input_token_estimate: init.input_token_estimate
} }));

const slot       = $input.first().json;
const g          = $getWorkflowStaticData('global');
const state      = g.loop_state || {};
const prevAnswer = state.prev_answer || '';

const plainText = [
  "STRICT OUTPUT FORMAT: plain text only.",
  "Forbidden: markdown symbols (* # _ ` ~), bold, italic, bullet points, numbered lists,",
  "LaTeX math notation, html, markdown, and the literal two-character sequence backslash-n.",
  "Use only regular letters, numbers, punctuation, and real line breaks.",
  "Write in flowing prose paragraphs.",
  ""
].join(" ") + "\n\n";

const promptText = !prevAnswer
  ? plainText + slot.input_text
  : plainText + slot.input_text
    + `\n\nYour answer so far (after ${slot.iteration - 1} iteration(s)):\n${prevAnswer}`
    + `\n\nContinue building on the above. Add more depth, detail or nuance not yet covered. Avoid repeating what was already said.`;

g.loop_state = { ...state, current_prompt_text: promptText };
return [{ json: { ...slot, prompt_text: promptText } }];

const raw = ($input.first().json.text || '');

let clean = raw
  // literal \n sequences the model outputs as text → real newline
  .replace(/\\n/g, '\n')
  // strip markdown bold / italic
  .replace(/\*\*([\s\S]*?)\*\*/g, '$1')
  .replace(/\*([\s\S]*?)\*/g,     '$1')
  .replace(/__([\s\S]*?)__/g,     '$1')
  .replace(/_([\s\S]*?)_/g,       '$1')
  // strip heading markers
  .replace(/^#{1,6}\s+/gm, '')
  // strip inline code backticks
  .replace(/`([^`\n]+)`/g, '$1')
  // convert markdown bullet lines "- text" / "* text" to plain "text"
  .replace(/^[\-\*\•]\s+/gm, '')
  // strip numbered list markers "1. " / "2) "
  .replace(/^\d+[\.\)]\s+/gm, '')
  // collapse 3+ blank lines into 2
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: { ...$input.first().json, text: clean } }];

const agentOutput = ($input.first().json.text || '').trim();
const slot        = $('Loop Over Items').item.json;
const g           = $getWorkflowStaticData('global');
const state       = g.loop_state || {};

const tokensOutputEst = Math.ceil(agentOutput.length / 4);
const tokensInputEst  = Math.ceil((state.current_prompt_text || '').length / 4);
const newCumul        = (state.cumul_tokens       || 0) + tokensOutputEst;
const newCumulInput   = (state.cumul_input_tokens || 0) + tokensInputEst;

// ── Termination rules (evaluated in priority order) ─────────────────────────
//
// Rule 1 — Output too short (< 30 tokens): answer is complete, no value in expanding
const tooShort         = tokensOutputEst < 30;
//
// Rule 2 — Cumulative depth reached (≥ 60 tokens total, only checked from iteration 2+)
const cumulSufficient  = (slot.iteration >= 2) && (newCumul >= 60);
//
// Rule 3 — Hard safety cap at iteration 3
const capReached       = slot.iteration >= 3;

const isDone = tooShort || cumulSufficient || capReached;

let terminationReason = 'continue';
if      (tooShort)          terminationReason = 'output_too_short_for_expansion';
else if (cumulSufficient)   terminationReason = 'cumulative_depth_reached';
else if (capReached)        terminationReason = 'max_iterations_safety_cap';

const traceEntry = {
  iteration:              slot.iteration,
  prompt_sent:            state.current_prompt_text || '',
  output:                 agentOutput,
  tokens_input_estimate:  tokensInputEst,
  tokens_output_estimate: tokensOutputEst,
  tokens_cumulative:      newCumul,
  is_done:                isDone,
  termination_reason:     terminationReason
};

const updatedTrace = [...(state.iterations_trace || []), traceEntry];
g.loop_state = { ...state, cumul_tokens: newCumul, cumul_input_tokens: newCumulInput, prev_answer: agentOutput, iterations_trace: updatedTrace };

return [{ json: {
  current_answer:       agentOutput,
  current_iteration:    slot.iteration,
  tokens_this_iter:     tokensOutputEst,
  cumul_tokens_after:   newCumul,
  cumul_input_tokens:   newCumulInput,
  is_done:              isDone,
  termination_reason:   terminationReason,
  too_short:            tooShort,
  cumul_sufficient:     cumulSufficient,
  cap_reached:          capReached,
  iterations_trace:     updatedTrace,
  input_text:           state.input_text,
  start_time_ms:        state.start_time_ms,
  input_token_estimate: state.input_token_estimate,
  max_iterations:       state.max_iterations
} }];

const data   = $input.first().json;
const endMs  = Date.now();
const latSec = parseFloat(((endMs - data.start_time_ms) / 1000).toFixed(2));

const totalOutputTokens = data.cumul_tokens;
const totalInputTokens  = data.cumul_input_tokens || data.input_token_estimate;
const totalTokens       = totalInputTokens + totalOutputTokens;

return [{ json: {
  user_prompt:  data.input_text,
  final_answer: data.final_answer,

  metadata: {
    pattern:          "Loop",
    pattern_category: "Deterministic Workflow Pattern",
    run_timestamp:    new Date().toISOString(),
    model:            "qwen2.5:14b",
    model_provider:   "Ollama (local)",
    temperature:      0.7,
    latency_ms:       endMs - data.start_time_ms,
    latency_seconds:  latSec,
    llm_calls_actual: data.iterations_run,
    llm_calls_max:    3,
    token_usage: {
      total_input_tokens:  totalInputTokens,
      total_output_tokens: totalOutputTokens,
      total_tokens:        totalTokens
    },
    status:             "completed",
    termination_reason: data.termination_reason
  },

  execution_trace: {
    iterations: data.iterations_trace,
    loop_config: {
      iter1_exit_if_output_below_tokens: 30,
      iter2_exit_if_cumul_above_tokens:  60,
      max_iterations:                    3
    },
    loop_behaviour: {
      iterations_run:           data.iterations_run,
      output_too_short:         data.too_short,
      cumulative_depth_reached: data.cumul_sufficient,
      safety_cap_triggered:     data.cap_reached,
      exited_early:             data.iterations_run < 3
    }
  }
} }];
